parameters.jsonBody:
={{
(() => {
  const gate = $json.laya_gate ?? {};
  const report = $('Final Report').first()?.json?.report ?? {};
  const internal = report.internal_analysis ?? {};
  const ti = report.threat_intelligence ?? {};

  let irisId = null;
  try { irisId = $('DFIR-IRIS Alert').first()?.json?.data?.alert_id ?? $('DFIR-IRIS Alert').first()?.json?.alert_id ?? null; } catch (e) { irisId = null; }
  const irisLink = irisId ? `https://REPLACE_WITH_IRIS_HOST/alerts?alert_ids=${irisId}&cid=1` : 'https://REPLACE_WITH_IRIS_HOST/alerts';

  const sev = String(report.severity ?? 'MEDIUM').toUpperCase();
  const COLORS = { CRITICAL: 0xB91C1C, HIGH: 0xDC2626, MEDIUM: 0xB45309, LOW: 0x1D4ED8 };
  const layerTxt = (gate.layer === null || gate.layer === undefined) ? 'n/a' : ('L' + gate.layer);

  const sceneLines = report.scene_lines || [];
  const fields = [
    { name: 'Severity', value: sev, inline: true },
    { name: 'Confidence', value: Math.round((Number(gate.confidence) || 0) * 100) + '%', inline: true },
    { name: 'Decision layer', value: layerTxt + (gate.stage ? ' - ' + gate.stage : ''), inline: true },
    { name: 'Host', value: '`' + (report.agent_name ?? 'n/a') + '`', inline: true },
    { name: 'Rule', value: '`' + (report.rule_id ?? 'n/a') + '` (level ' + (report.rule_level ?? 'n/a') + ')', inline: true },
    { name: 'Verdict', value: String(gate.verdict ?? 'n/a').replace(/_/g, ' '), inline: true },
  ];

  if (report.analysis_type === 'internal') {
    fields.push({ name: 'Account', value: '`' + (report.srcuser ?? internal.user ?? 'n/a') + '`', inline: true });
    if (internal.command) fields.push({ name: 'Command', value: '`' + internal.command + '`', inline: false });
    if (internal.mitre && internal.mitre.ids && internal.mitre.ids.length) {
      fields.push({ name: 'MITRE ATT&CK', value: internal.mitre.ids.join(', '), inline: false });
    }
  } else {
    fields.push({ name: 'Source IP', value: '`' + (report.source_ip ?? 'n/a') + '`', inline: true });
    if (ti.abuseipdb?.country) {
      fields.push({ name: 'Country / Location', value: String(ti.abuseipdb.country), inline: true });
    }
    fields.push({
      name: 'Threat intel',
      value: 'AbuseIPDB ' + (ti.abuseipdb?.confidence_score ?? ti.abuseipdb?.score ?? 0) + '%'
        + '  |  VirusTotal ' + (ti.virustotal?.malicious ?? 0) + ' engines'
        + '  |  GreyNoise ' + (ti.greynoise?.classification ?? 'unknown'),
      inline: false
    });
  }

  if (sceneLines.length) fields.push({ name: 'Complete alert scene', value: ('```\n' + sceneLines.join('\n') + '\n```').slice(0, 1020), inline: false });
  if (gate.reason) fields.push({ name: 'Decision reason', value: String(gate.reason).slice(0, 500), inline: false });
  fields.push({ name: 'Recommended action', value: String(report.recommendation ?? 'Review in DFIR-IRIS').slice(0, 500), inline: false });

  const embed = {
    username: 'Laya SOC',
    embeds: [{
      title: ('[' + sev + '] ' + String(report.description ?? 'Security Incident')).slice(0, 250),
      url: irisLink,
      description: String(report.summary ?? '').slice(0, 900),
      color: COLORS[sev] ?? 0x334155,
      fields: fields.slice(0, 25),
      footer: {
        text: 'Laya ' + (gate.correlation_id ?? 'n/a') + '  |  policy ' + (gate.policy_version ?? 'n/a')
              + '  |  IRIS #' + (irisId ?? 'not created')
      },
      timestamp: new Date().toISOString()
    }]
  };
  return JSON.stringify(embed);
})()
}}

