(() => {
  const report = $('Final Report').first().json.report ?? {};
  const internal = report.internal_analysis ?? {};
  const ai = report.summary ?? 'Tier-2 SOAR analysis completed';

  const esc = (value) =>
    String(value ?? 'N/A')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

  const join = (value) =>
    Array.isArray(value) && value.length
      ? value.map(esc).join(', ')
      : 'N/A';

  const ti = report.threat_intelligence ?? {};
  const abuse = ti.abuseipdb ?? {};
  const vt = ti.virustotal ?? {};
  const otx = ti.otx ?? {};
  const grey = ti.greynoise ?? {};
  const threatfox = ti.threatfox ?? {};
  const leakix = ti.leakix ?? {};
  const assessment = report.assessment ?? {};
  const generated = report.generated_at ? esc(report.generated_at) : 'N/A';
  const separator = '────────────────────';

  if (report.analysis_type === 'internal') {
    const gate = $json.laya_gate ?? {};
    let irisId = null;
    try { irisId = $('DFIR-IRIS Alert').first()?.json?.data?.alert_id ?? null; } catch (e) { irisId = null; }
    const idLine = '\nAlert ID: ' + (gate.correlation_id || 'n/a') + (irisId ? ('  |  IRIS case: #' + irisId) : '');
    return `SOC INCIDENT REPORT' + idLine + '

Severity: ${esc(report.severity)}
Agent: ${esc(report.agent_name)}
Rule Level: ${esc(report.rule_level)}

Description:
${esc(report.description)}

${separator}
