${separator}

Rule ID:
${esc(internal.rule_id)}

User:
${esc(internal.user)}

Target User:
${esc(internal.target_user)}

Command:
${esc(internal.command)}

MITRE ATT&CK:
${join(internal.mitre?.ids)}

Tactics:
${join(internal.mitre?.tactics)}

Techniques:
${join(internal.mitre?.techniques)}

${separator}
ASSESSMENT
${separator}

Risk Score: ${esc(report.risk_score)}/100
Confidence: ${esc(assessment.confidence)}

${separator}
SUMMARY
${separator}

${esc(report.summary)}

${separator}
RECOMMENDED ACTION
${separator}

${esc(report.recommendation)}

${separator}
GENERATED
${separator}

${generated}`;
  }

  return `SOC INCIDENT REPORT

Severity: ${esc(report.severity)}
Agent: ${esc(report.agent_name)}
Rule Level: ${esc(report.rule_level)}

Description:
${esc(report.description)}

Source IP:
${esc(report.source_ip)}

${separator}
THREAT INTELLIGENCE
${separator}

AbuseIPDB:
Status: ${esc(abuse.status)}
Confidence Score: ${esc(abuse.confidence_score ?? abuse.score)}/100
Reports: ${esc(abuse.reports)}
Country: ${esc(abuse.country)}
ISP: ${esc(abuse.isp)}

VirusTotal:
Status: ${esc(vt.status)}
Malicious: ${esc(vt.malicious)}
Reputation: ${esc(vt.reputation)}

AlienVault OTX:
Status: ${esc(otx.status)}
Pulses: ${esc(otx.pulses)}

GreyNoise:
Status: ${esc(grey.status)}
Classification: ${esc(grey.classification)}
Noise: ${esc(grey.noise)}

ThreatFox:
Status: ${esc(threatfox.status)}

${separator}
ASSESSMENT
${separator}

Risk Score: ${esc(report.risk_score)}/100
Confidence: ${esc(assessment.confidence)}
Provider Coverage: ${esc(assessment.provider_coverage)}%

${separator}
SUMMARY
${separator}

${esc(report.summary)}

${separator}
