parameters.jsCode:
const data = $json;
const incident = data.incident ?? {};

const severity = String(
  data.severity ?? incident.severity ?? "MEDIUM"
).toUpperCase();

const ruleLevel = Number(incident.rule_level ?? 0);
const ruleId = incident.rule_id ?? incident.internal_analysis?.rule_id ?? incident.original_alert?.rule?.id ?? incident.rule?.id ?? 'N/A';
const agentName = incident.agent_name ?? incident.original_alert?.agent?.name ?? 'blusoc';
const wazuhAlertId = incident.original_alert?.id ?? incident.alert_id ?? 'N/A';
const description = incident.description ?? incident.original_alert?.rule?.description ?? 'Security Incident';
const sourceIp = incident.source_ip ?? incident.original_alert?.data?.srcip ?? 'N/A';
const riskScore = Number(incident.risk_score ?? incident.assessment?.risk_score ?? 0);
const confidence = incident.assessment?.confidence ?? 'LOW';
const verdict = incident.assessment?.verdict ?? 'ALERT_INGESTED';
const analysisType = incident.analysis_type ?? 'external';
const ti = incident.threat_intelligence ?? {};
const evidenceList = incident.assessment?.evidence ?? [];
const rawLog = incident.original_alert?.full_log ?? incident.raw_log ?? incident.description ?? 'Log telemetry verified.';


// ---------- complete alert scene (what an analyst actually needs) ----------
function buildSceneLines(a) {
  if (!a || typeof a !== 'object') return [];
  const r = a.rule || {}, d = a.data || {}, ag = a.agent || {};
  const al = (d.alert && typeof d.alert === 'object') ? d.alert : {};
  const meta = (al.metadata && typeof al.metadata === 'object') ? al.metadata : {};
  const http = (d.http && typeof d.http === 'object') ? d.http : {};
  const win = (d.win && typeof d.win === 'object') ? d.win : {};
  const ev = (win.eventdata && typeof win.eventdata === 'object') ? win.eventdata : {};
  const one = (v) => Array.isArray(v) ? v.join(',') : (v == null ? '' : String(v));
  const L = [];

  L.push('Sensor / Agent   : ' + (ag.name || 'unknown') + (ag.ip ? ('  (' + ag.ip + ')') : ''));
  L.push('Rule             : ' + (r.id || '?') + '  level ' + (r.level == null ? '?' : r.level));
  L.push('Description      : ' + (r.description || 'n/a'));
  if (r.groups) L.push('Rule groups      : ' + one(r.groups));

  const sip = d.src_ip || d.srcip || (al.source && al.source.ip);
  const dip = d.dest_ip || d.dstip || (al.target && al.target.ip);
  const sport = d.src_port || d.srcport || (al.source && al.source.port);
  const dport = d.dest_port || d.dstport || (al.target && al.target.port);
  if (sip || dip) {
    L.push('Network          : ' + (sip || '?') + (sport ? (':' + sport) : '') +
           '  ->  ' + (dip || '?') + (dport ? (':' + dport) : '') +
           (d.proto ? ('   proto=' + d.proto) : '') +
           (d.app_proto ? ('   app=' + d.app_proto) : '') +
           (d.direction ? ('   dir=' + d.direction) : ''));
  }
  if (al.signature) {
    L.push('Signature        : [' + (al.category || 'uncategorised') + '] ' + al.signature);
    L.push('Signature detail : id=' + (al.signature_id || '?') + '  severity=' + (al.severity || '?') +
           '  action=' + (al.action || '?') +
           (al.rev ? ('  rev=' + al.rev) : ''));
  }
  const tm = [];
  if (meta.cve) tm.push('CVE=' + one(meta.cve));
  if (meta.tag) tm.push('tags=' + one(meta.tag));
  if (meta.confidence) tm.push('confidence=' + one(meta.confidence));
  if (meta.signature_severity) tm.push('signature_severity=' + one(meta.signature_severity));
  if (meta.affected_product) tm.push('affected_product=' + one(meta.affected_product));
  if (meta.attack_target) tm.push('attack_target=' + one(meta.attack_target));
  if (meta.mitre_technique_id) tm.push('technique=' + one(meta.mitre_technique_id) +
                                       (meta.mitre_technique_name ? (' ' + one(meta.mitre_technique_name)) : ''));
  if (meta.mitre_tactic_name) tm.push('tactic=' + one(meta.mitre_tactic_name));
  if (tm.length) L.push('Threat metadata  : ' + tm.join('  |  '));

  if (http.http_method) {
    L.push('HTTP request     : ' + http.http_method + ' ' + (http.hostname || '') + (http.url || '') +
           (http.protocol ? ('  ' + http.protocol) : ''));
    if (http.http_user_agent) L.push('HTTP user-agent  : ' + String(http.http_user_agent).slice(0, 160));
  }
  if (d.flow) {
    L.push('Flow             : in ' + (d.flow.pkts_toserver || 0) + ' pkts/' + (d.flow.bytes_toserver || 0) +
           ' B   out ' + (d.flow.pkts_toclient || 0) + ' pkts/' + (d.flow.bytes_toclient || 0) + ' B');
  }

  const acct = d.srcuser || d.dstuser || d.user || ev.user || (d.office365 && d.office365.UserId);
  if (acct) L.push('Account          : ' + acct);
  const cmd = d.command || (d.audit && d.audit.command);
  if (cmd) L.push('Command          : ' + cmd);
  const img = ev.image || ev.Image || d.process;
  if (img) L.push('Process          : ' + img);
  const pimg = ev.parentImage || ev.ParentImage;
  if (pimg) L.push('Parent process   : ' + pimg);
  const cli = ev.commandLine || ev.CommandLine;
  if (cli) L.push('Process command  : ' + cli);
  const fh = d.md5 || d.sha1 || d.sha256 || d.hash || (d.syscheck && (d.syscheck.md5_after || d.syscheck.sha256_after));
  if (fh) L.push('File hash        : ' + fh);
  const fp = d.file || d.path || (d.syscheck && d.syscheck.path);
  if (fp) L.push('File / path      : ' + fp);
  const op = d.office365 && d.office365.Operation;
  if (op) L.push('Cloud operation  : ' + op);
  const vuln = (d.vulnerability && typeof d.vulnerability === 'object') ? d.vulnerability : null;
  if (vuln) L.push('Vulnerability    : ' + (vuln.cve || '') + '  severity=' + (vuln.severity || '') + '  status=' + (vuln.status || ''));
  if (r.mitre) L.push('MITRE ATT&CK     : ' + one(r.mitre.id) + '  ' + one(r.mitre.tactic) + '  ' + one(r.mitre.technique));
  if (a.location) L.push('Log location     : ' + a.location);
  if (a.full_log) L.push('Raw event        : ' + String(a.full_log).slice(0, 1400));
  return L;
}

const sceneAlert = incident.original_alert ?? null;
const sceneLines = buildSceneLines(sceneAlert);

let summaryText = "";
let recommendationText = "";
let descriptionText = "";

if (analysisType === 'internal') {
  const internal = incident.internal_analysis ?? {};
  const userStr = internal.user || 'system';
  const targetStr = internal.target_user || 'root';
  const cmdStr = internal.command || 'N/A';
  const mitreStr = (internal.mitre?.ids?.length > 0)
    ? `${internal.mitre.ids.join(', ')} (${internal.mitre.tactics?.join(', ') || ''} - ${internal.mitre.techniques?.join(', ') || ''})`
    : 'N/A';

  summaryText = `Internal host security event detected on ${agentName}. User: ${userStr}, Command: ${cmdStr}. Action triggered rule level ${ruleLevel}.`;
  recommendationText = "Verify user authorization for executed commands, inspect audit logs, and ensure least-privilege access.";

  descriptionText = `[ENTERPRISE SOAR INCIDENT ASSESSMENT]
Severity       : ${severity} (Risk Score: ${riskScore}/100)
Target Agent   : ${agentName}
Rule ID        : ${ruleId} (Level ${ruleLevel})
Classification : INTERNAL (Confidence: ${confidence})
Pre-assessment : ${verdict} (heuristic - the authoritative verdict is the Laya decision below)

[INTERNAL THREAT DETAILS]
User           : ${userStr}
Target User    : ${targetStr}
Command        : ${cmdStr}
MITRE ATT&CK   : ${mitreStr}

[SOC TIER-2 ANALYST SUMMARY]
${summaryText}

[CORROBORATING EVIDENCE & ARTIFACTS]
${evidenceList.length > 0 ? evidenceList.map(e => '- ' + e).join('\n') : '- Internal host security event verified.'}

[RECOMMENDED SOC ACTIONS]
${recommendationText}

[COMPLETE ALERT SCENE]
${sceneLines.length ? sceneLines.join('\n') : '(no structured detail)'}

[LOG EXCERPT]
${rawLog}`;

} else {
  if (verdict === 'TRUE_POSITIVE_THREAT') {
    summaryText = `High-confidence malicious activity detected from ${sourceIp} targeting ${agentName}. Threat intel corroboration confirmed across ${incident.assessment?.malicious_sources?.join(', ') || 'multiple feeds'} with Risk Score ${riskScore}/100.`;
    recommendationText = "Block external source IP at perimeter firewall, isolate affected hosts, and inspect established network sessions.";
  } else {
    summaryText = `SOC training/reconnaissance alert from ${sourceIp} against ${agentName} (Rule ${ruleId} - ${description}). No external threat feeds flagged malicious reputation.`;
    recommendationText = "Review event in DFIR-IRIS, triage source IP in OSINT tools, and verify if associated with training scenario.";
  }

  const abuseScore = ti.abuseipdb?.confidence_score ?? ti.abuseipdb?.confidence ?? ti.abuseipdb?.score ?? 'N/A';
  const vtMalicious = ti.virustotal?.malicious ?? '0';
  const vtRep = ti.virustotal?.reputation ?? '0';
  const greyClass = ti.greynoise?.classification ?? (ti.greynoise?.noise ? 'Benign Scanner' : 'Unknown');
  const otxPulses = ti.otx?.pulses ?? '0';
  const tfStatus = ti.threatfox?.status ?? 'No Hit';

  descriptionText = `[ENTERPRISE SOAR INCIDENT ASSESSMENT]
Severity       : ${severity} (Risk Score: ${riskScore}/100)
Target Agent   : ${agentName}
Rule ID        : ${ruleId} (Level ${ruleLevel})
Classification : EXTERNAL (Confidence: ${confidence})
Verdict        : ${verdict}

[THREAT INTELLIGENCE SCORECARD]
Source IP      : ${sourceIp}
AbuseIPDB      : ${abuseScore}% confidence (Country: ${ti.abuseipdb?.country || 'N/A'}, ISP: ${ti.abuseipdb?.isp || 'N/A'})
VirusTotal     : ${vtMalicious} malicious engines (Reputation: ${vtRep})
GreyNoise      : ${greyClass} (Background Noise: ${ti.greynoise?.noise ? 'Yes' : 'No'})
AlienVault OTX : ${otxPulses} pulses
ThreatFox      : ${tfStatus}

[SOC TIER-2 ANALYST SUMMARY]
${summaryText}

[CORROBORATING EVIDENCE & ARTIFACTS]
${evidenceList.length > 0 ? evidenceList.map(e => '- ' + e).join('\n') : '- Threat intelligence enrichment recorded.'}

[RECOMMENDED SOC ACTIONS]
${recommendationText}

[COMPLETE ALERT SCENE]
${sceneLines.length ? sceneLines.join('\n') : '(no structured detail)'}

[LOG EXCERPT]
${rawLog}`;
}

const report = {
  agent_name: agentName,
  scene_lines: sceneLines,
  raw_alert: sceneAlert,
  srcuser: incident.original_alert?.data?.srcuser
        ?? incident.original_alert?.data?.user
        ?? incident.internal_analysis?.user
        ?? null,
  wazuh_alert_id: wazuhAlertId,
  rule_id: ruleId,
  rule_level: ruleLevel,
  description: description,
  source_ip: sourceIp,
  ioc: incident.ioc ?? { type: analysisType === 'internal' ? 'internal' : 'public_ip', value: sourceIp },
  severity: severity,
  risk_score: riskScore,
  analysis_type: analysisType,
  threat_intelligence: ti,
  internal_analysis: incident.internal_analysis ?? null,
  assessment: {
    ...incident.assessment,
    confidence: confidence,
    verdict: verdict,
    summary: summaryText,
    recommendation: recommendationText
  },
  summary: summaryText,
  recommendation: recommendationText
};

const iris_payload = {
  alert_title: `[SOAR ${severity}] ${description} on ${agentName}`,
  alert_description: descriptionText,
  alert_source: "Wazuh-SOAR",
  alert_source_ref: `soar-${ruleId}-${agentName}-${sourceIp || (d.srcuser || 'local')}`,
  alert_severity_id: (severity === 'CRITICAL') ? 6 : (severity === 'HIGH') ? 5 : (severity === 'MEDIUM') ? 1 : 4,
  alert_status_id: 1,
  alert_customer_id: 1,
  alert_tags: `wazuh,soar_enriched,rule_${ruleId},${analysisType},${severity.toLowerCase()}`
};

return [{
  json: {
    report,
    severity,
    iris_description: descriptionText,
    iris_payload: iris_payload
  }
}];

const input = $json;

const incident = input.incident ?? {};
const assessment = incident.assessment ?? {};

const ruleLevel = Number(incident.rule_level ?? 0);
const riskScore = Number(incident.risk_score ?? assessment.risk_score ?? 0);

const ti = incident.threat_intelligence ?? {};

const abuse = ti.abuseipdb ?? {};
const vt = ti.virustotal ?? {};
const grey = ti.greynoise ?? {};
const tf = ti.threatfox ?? {};
const otx = ti.otx ?? {};
const leakix = ti.leakix ?? {};

const abuseScore = Number(abuse.score ?? 0);
const vtMalicious = Number(vt.malicious ?? 0);
const vtSuspicious = Number(vt.suspicious ?? 0);
const otxPulses = Number(otx.pulses ?? 0);

const greyMalicious =
  grey.classification === "malicious";

const greyNoise =
  grey.noise === true;

const threatFoxHit =
  tf.status === "success";

const leakixUnavailable =
  leakix.status === "unavailable";


// ============================================================
// CORROBORATION
// ============================================================

const maliciousSignals = [];

if (greyMalicious) {
  maliciousSignals.push("GreyNoise");
}

if (abuseScore >= 80) {
  maliciousSignals.push("AbuseIPDB");
}

if (vtMalicious > 0) {
  maliciousSignals.push("VirusTotal");
}

if (otxPulses > 0) {
  maliciousSignals.push("OTX");
}

if (threatFoxHit) {
  maliciousSignals.push("ThreatFox");
}

const corroboratingSources =
  maliciousSignals.length;


// ============================================================
// FINAL SEVERITY
// ============================================================
//
// Start from Wazuh severity and use TI evidence to escalate.
// TI provider failure never escalates severity.
//

let severity = "LOW";

if (ruleLevel >= 15) {
  severity = "CRITICAL";
} else if (ruleLevel >= 12) {
  severity = "HIGH";
} else if (ruleLevel >= 8) {
  severity = "MEDIUM";
}


// Strong correlated evidence
if (
  riskScore >= 80 &&
  corroboratingSources >= 3
) {
  severity = "CRITICAL";
}


// Confirmed ThreatFox IOC
if (threatFoxHit) {
  severity = "CRITICAL";
}


// Strong malware consensus
if (
  vtMalicious >= 10 &&
  corroboratingSources >= 2
) {
  severity = "CRITICAL";
}


// Significant TI evidence
if (
  severity !== "CRITICAL" &&
  riskScore >= 50 &&
  corroboratingSources >= 2
) {
  severity = "HIGH";
}


// Single strong signal
if (
  severity === "LOW" &&
  (
    abuseScore >= 80 ||
    vtMalicious >= 1 ||
    greyMalicious ||
    otxPulses > 0
  )
) {
  severity = "HIGH";
}


// ============================================================
// TRUSTED INFRASTRUCTURE
// ============================================================
//
// Trusted ISP alone must NEVER override malicious evidence.
//

const trustedISP = [
  "Google LLC",
  "Cloudflare",
  "Microsoft",
  "Amazon",
  "Akamai"
];

const isp =
  String(abuse.isp ?? "");

const trusted =
  trustedISP.some(name =>
    isp.toLowerCase().includes(
      name.toLowerCase()
    )
  );

const noMaliciousEvidence =
  corroboratingSources === 0 &&
  abuseScore === 0 &&
  vtMalicious === 0 &&
  !greyMalicious &&
  !threatFoxHit &&
  otxPulses === 0;

if (
  trusted &&
  noMaliciousEvidence
) {
  if (ruleLevel >= 15) {
    severity = "HIGH";
  } else if (ruleLevel >= 8) {
    severity = "MEDIUM";
  } else {
    severity = "LOW";
  }
}


// ============================================================
// RETURN
// ============================================================

return {
  json: {
    ...input,

    severity,

    severity_factors: {
      rule_level: ruleLevel,
      risk_score: riskScore,

      abuseipdb_score: abuseScore,
      virustotal_malicious: vtMalicious,
      virustotal_suspicious: vtSuspicious,

      greynoise_classification:
        grey.classification ?? null,

      greynoise_noise: greyNoise,

      threatfox_hit: threatFoxHit,

      otx_pulses: otxPulses,

      corroborating_sources:
        corroboratingSources,

      malicious_sources:
        maliciousSignals,

      trusted_isp: trusted,

      leakix_unavailable:
        leakixUnavailable
    }
  }
};

// ============================================================
// INCIDENT SUMMARY
// ============================================================
// Input:
//   { incident: { ... } }
//
// Both External Incident and Internal Incident already produce
// the SAME schema:
//   { incident: {...} }
//
// This node must therefore ALWAYS read from data.incident.
// It must NOT expect alert/threat_intelligence/assessment at
// the top level.
//
// Output:
//   { incident: {...} }
// ============================================================

const data = $input.first().json ?? {};
const incidentInput = data.incident ?? {};

if (!incidentInput || typeof incidentInput !== 'object') {
  return [];
}

// ------------------------------------------------------------
// Helper functions
// ------------------------------------------------------------

const safeString = (value, fallback = null) => {
  if (value === null || value === undefined) {
    return fallback;
  }

  const text = String(value).trim();
  return text ? text : fallback;
};

const safeArray = (value) => {
  return Array.isArray(value) ? value : [];
};

const safeNumber = (value, fallback = 0) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
};

// ------------------------------------------------------------
// Basic alert context
// ------------------------------------------------------------

const sourceIp =
  safeString(incidentInput.source_ip);

const agentName =
  safeString(incidentInput.agent_name);

const ruleLevel =
  safeNumber(incidentInput.rule_level, 0);

const description =
  safeString(
    incidentInput.description,
    'Unknown security event'
  );

const analysisType =
  incidentInput.analysis_type === 'internal'
    ? 'internal'
    : 'external';

// ------------------------------------------------------------
// IOC
// ------------------------------------------------------------

const inputIoc =
  incidentInput.ioc ??
  {
    type: null,
    value: null
  };

const ioc = {
  type:
    safeString(inputIoc.type),

  value:
    safeString(
      inputIoc.value
    )
};

// ------------------------------------------------------------
// Threat Intelligence
// ------------------------------------------------------------

const inputTi =
  incidentInput.threat_intelligence ??
  {};

const abuseInput =
  inputTi.abuseipdb ??
  {};

const vtInput =
  inputTi.virustotal ??
  {};

const greyInput =
  inputTi.greynoise ??
  {};

const threatFoxInput =
  inputTi.threatfox ??
  {};

const otxInput =
  inputTi.otx ??
  {};

const leakixInput =
  inputTi.leakix ??
  {};

// Preserve the existing TI values.
// Do NOT convert a valid provider result into null.
//
// Note: the existing AbuseIPDB normalizer may use "score"
// internally while Telegram expects "confidence_score".
// Preserve both where possible for compatibility.

const threatIntelligence = {

  abuseipdb: {
    status:
      safeString(
        abuseInput.status,
        'not_checked'
      ),

    confidence_score:
      abuseInput.confidence_score ??
      abuseInput.score ??
      null,

    score:
      abuseInput.score ??
      abuseInput.confidence_score ??
      null,

    reports:
      abuseInput.reports ??
      abuseInput.total_reports ??
      null,

    country:
      abuseInput.country ??
      null,

    isp:
      abuseInput.isp ??
      null,

    domain:
      abuseInput.domain ??
      null,

    tor:
      abuseInput.tor ??
      null
  },

  virustotal: {
    status:
      safeString(
        vtInput.status,
        'not_checked'
      ),

    malicious:
      vtInput.malicious ??
      null,

    suspicious:
      vtInput.suspicious ??
      null,

    harmless:
      vtInput.harmless ??
      null,

    undetected:
      vtInput.undetected ??
      null,

    reputation:
      vtInput.reputation ??
      null
  },

  greynoise: {
    status:
      safeString(
        greyInput.status,
        'not_checked'
      ),

    classification:
      greyInput.classification ??
      null,

    noise:
      greyInput.noise ??
      null,

    riot:
      greyInput.riot ??
      null
  },

  threatfox: {
    status:
      safeString(
        threatFoxInput.status,
        'not_checked'
      ),

    result:
      threatFoxInput.result ??
      null
  },

  otx: {
    status:
      safeString(
        otxInput.status,
        'not_checked'
      ),

    pulses:
      otxInput.pulses ??
      null,

    reputation:
      otxInput.reputation ??
      null
  },

  leakix: {
    status:
      safeString(
        leakixInput.status,
        'not_checked'
      ),

    services:
      safeArray(
        leakixInput.services
      ),

    error:
      leakixInput.error ??
      null
  }
};

// ------------------------------------------------------------
// Internal Analysis
// ------------------------------------------------------------

const inputInternal =
  incidentInput.internal_analysis;

let internalAnalysis = null;

if (
  inputInternal &&
  typeof inputInternal === 'object'
) {

  const mitreInput =
    inputInternal.mitre ??
    {};

  internalAnalysis = {

    rule_id:
      inputInternal.rule_id ??
      null,

    user:
      inputInternal.user ??
      null,

    target_user:
      inputInternal.target_user ??
      null,

    command:
      inputInternal.command ??
      null,

    mitre: {

      ids:
        safeArray(
          mitreInput.ids
        ),

      tactics:
        safeArray(
          mitreInput.tactics
        ),

      techniques:
        safeArray(
          mitreInput.techniques
        )
    }
  };
}

// ------------------------------------------------------------
// Assessment
// ------------------------------------------------------------

const inputAssessment =
  incidentInput.assessment ??
  {};

const maliciousSources =
  safeArray(
    inputAssessment.malicious_sources
  );

const evidence =
  safeArray(
    inputAssessment.evidence
  );

const providerFailures =
  safeArray(
    inputAssessment.provider_failures
  );

const assessment = {

  confidence:
    safeString(
      inputAssessment.confidence,
      analysisType === 'internal'
        ? 'HIGH'
        : 'LOW'
    ),

  provider_coverage:
    safeNumber(
      inputAssessment.provider_coverage,
      0
    ),

  has_malicious_evidence:
    Boolean(
      inputAssessment.has_malicious_evidence
    ),

  malicious_sources:
    maliciousSources,

  evidence:
    evidence,

  provider_failures:
    providerFailures
};

// ------------------------------------------------------------
// Severity
// ------------------------------------------------------------

let severity =
  safeString(
    incidentInput.severity
  );

let riskScore =
  safeNumber(
    incidentInput.risk_score,
    0
  );

// If a valid severity already exists, preserve it.
// Otherwise derive it from the Wazuh rule level.

if (!severity) {

  if (ruleLevel >= 15) {

    severity = 'CRITICAL';
    riskScore = Math.max(
      riskScore,
      90
    );

  } else if (ruleLevel >= 12) {

    severity = 'HIGH';
    riskScore = Math.max(
      riskScore,
      70
    );

  } else if (ruleLevel >= 8) {

    severity = 'MEDIUM';
    riskScore = Math.max(
      riskScore,
      40
    );

  } else {

    severity = 'LOW';
    riskScore = Math.max(
      riskScore,
      10
    );
  }
}

// ------------------------------------------------------------
// Summary
// ------------------------------------------------------------

let summary =
  safeString(
    incidentInput.summary
  );

if (!summary) {

  if (analysisType === 'external') {

    const iocValue =
      ioc.value ??
      sourceIp ??
      'unknown';

    summary =
      `Multiple threat-intelligence sources were checked for ` +
      `IOC ${iocValue}. ` +
      `The resulting evidence was incorporated into the incident assessment.`;

  } else {

    const user =
      safeString(
        internalAnalysis?.user,
        'unknown'
      );

    const targetUser =
      safeString(
        internalAnalysis?.target_user,
        'unknown'
      );

    summary =
      `Internal security event detected: ${description}. ` +
      `User ${user} targeted ${targetUser}.`;
  }
}

// ------------------------------------------------------------
// Recommendation
// ------------------------------------------------------------

let recommendation =
  safeString(
    incidentInput.recommendation
  );

if (!recommendation) {

  const descriptionLower =
    description.toLowerCase();

  if (analysisType === 'external') {

    if (
      severity === 'CRITICAL'
    ) {

      recommendation =
        `Investigate the incident immediately, validate the ` +
        `activity, review the affected asset and surrounding ` +
        `events, and consider blocking or containing the IOC ` +
        `if malicious activity is confirmed.`;

    } else if (
      severity === 'HIGH'
    ) {

      recommendation =
        `Investigate the incident promptly, validate the IOC ` +
        `and related activity, review surrounding events, and ` +
        `consider blocking the IOC if malicious behavior is confirmed.`;

    } else {

      recommendation =
        `Review the alert and continue monitoring for additional ` +
        `suspicious activity.`;
    }

  } else {

    // Internal alerts should get recommendations based on the
    // actual event instead of assuming every event is privilege
    // escalation.

    if (
      /malware|trojan|ransom|backdoor|malicious file|falcon/.test(
        descriptionLower
      )
    ) {

      recommendation =
        `Investigate the affected endpoint, inspect the detected ` +
        `file or process, review process execution and file ` +
        `provenance, and quarantine or isolate the host if ` +
        `malicious activity is confirmed.`;

    } else if (
      /privilege|escalat|administrator|root/.test(
        descriptionLower
      )
    ) {

      recommendation =
        `Investigate the privilege-related activity, verify ` +
        `whether the administrative action was authorized, and ` +
        `review related authentication and process activity.`;

    } else if (
      /brute|credential|authentication|login|unauthorized/.test(
        descriptionLower
      )
    ) {

      recommendation =
        `Review the authentication activity, verify whether the ` +
        `source and account activity were authorized, and inspect ` +
        `related login failures or successful access.`;

    } else if (
      severity === 'CRITICAL'
    ) {

      recommendation =
        `Investigate the incident immediately, review the affected ` +
        `host and surrounding events, and contain the activity ` +
        `if unauthorized behavior is confirmed.`;

    } else {

      recommendation =
        `Review the event, validate whether the activity was ` +
        `authorized, and inspect related endpoint or authentication ` +
        `activity.`;
    }
  }
}

// ------------------------------------------------------------
// Final normalized incident
// ------------------------------------------------------------

const incident = {
  original_alert: incidentInput.original_alert ?? null,
  rule_id: incidentInput.rule_id ?? incidentInput.internal_analysis?.rule_id ?? incidentInput.original_alert?.rule?.id ?? null,
  raw_log: incidentInput.raw_log ?? incidentInput.original_alert?.full_log ?? null,

  source_ip:
    sourceIp,

  agent_name:
    agentName,

  rule_level:
    incidentInput.rule_level ?? null,

  description:
    description,

  severity:
    severity,

  risk_score:
    riskScore,

  ioc:
    ioc,

  analysis_type:
    analysisType,

  internal_analysis: internalAnalysis,
  rule_id: incidentInput.rule_id,
  original_alert: incidentInput.original_alert,
  raw_log: incidentInput.raw_log,

  threat_intelligence:
    threatIntelligence,

  assessment:
    assessment,

  summary:
    summary,

  recommendation:
    recommendation,

  // Preserve generated timestamp if an earlier node supplied it.
  generated_at:
    incidentInput.generated_at ??
    new Date().toISOString()
};

// ------------------------------------------------------------
// Return exactly ONE common schema
// ------------------------------------------------------------

return [
  {
    json: {
      incident
    }
  }
];

