const items = $input.all();

// ============================================================
// ORIGINAL WAZUH ALERT
// ============================================================

let original = {};

try {
  original = $('IOC Extraction').first().json ?? {};
} catch (error) {
  original = {};
}


// ============================================================
// BASE RESULT
// ============================================================

const rawAlert = original.original_alert ?? original;
const result = {
  original_alert: rawAlert,
  rule_id: rawAlert.rule?.id ?? original.rule_id ?? 'N/A',
  raw_log: rawAlert.full_log ?? null,
  rule_level: original.rule_level ?? null,
  agent_name: original.agent_name ?? null,
  description: original.description ?? null,
  source_ip: original.source_ip ?? null,

  ioc: {
    type: original.ioc?.type ?? null,
    value: original.ioc?.value ?? null,
  },

  threat_intelligence: {
    greynoise: {
      status: "not_checked",
      classification: null,
      noise: null,
      riot: null,
    },

    abuseipdb: {
      status: "not_checked",
      confidence: null,
      reports: null,
      tor: null,
      country: null,
      isp: null,
      domain: null,
    },

    otx: {
      status: "not_checked",
      pulses: null,
    },

    virustotal: {
      status: "not_checked",
      reputation: null,
      malicious: null,
      suspicious: null,
      harmless: null,
      undetected: null,
    },

    threatfox: {
      status: "not_checked",
      result: null,
    },

    leakix: {
      status: "not_checked",
      services: [],
      error: null,
    },
  },

  risk_score: 0,

  provider_coverage: 0,

  assessment_confidence: "LOW",

  evidence: [],

  sources: [],
};


// ============================================================
// HELPERS
// ============================================================

function addSource(name) {
  if (!result.sources.includes(name)) {
    result.sources.push(name);
  }
}

function addEvidence(message) {
  if (!result.evidence.includes(message)) {
    result.evidence.push(message);
  }
}


// ============================================================
// PROCESS TI RESULTS
// ============================================================

for (const item of items) {
  const data = item.json ?? {};

  // ----------------------------------------------------------
  // GreyNoise
  // ----------------------------------------------------------

  if (
    data.classification !== undefined ||
    data.noise !== undefined ||
    data.riot !== undefined
  ) {
    result.threat_intelligence.greynoise = {
      status: "success",
      classification: data.classification ?? null,
      noise: data.noise ?? null,
      riot: data.riot ?? null,
    };

    addSource("GreyNoise");

    if (data.classification === "malicious") {
      result.risk_score += 30;

      addEvidence(
        "GreyNoise classified the IP as malicious"
      );
    } else if (data.classification === "benign") {
      addEvidence(
        "GreyNoise classified the IP as benign"
      );
    }
  }


  // ----------------------------------------------------------
  // AbuseIPDB
  // ----------------------------------------------------------

  if (data.data?.abuseConfidenceScore !== undefined) {
    const score =
      Number(data.data.abuseConfidenceScore) || 0;

    const ISO_MAP = {
      "AF": "Afghanistan", "AL": "Albania", "DZ": "Algeria", "AD": "Andorra", "AO": "Angola", "AG": "Antigua and Barbuda",
      "AR": "Argentina", "AM": "Armenia", "AU": "Australia", "AT": "Austria", "AZ": "Azerbaijan", "BS": "Bahamas",
      "BH": "Bahrain", "BD": "Bangladesh", "BB": "Barbados", "BY": "Belarus", "BE": "Belgium", "BZ": "Belize",
      "BJ": "Benin", "BT": "Bhutan", "BO": "Bolivia", "BA": "Bosnia and Herzegovina", "BW": "Botswana", "BR": "Brazil",
      "BN": "Brunei Darussalam", "BG": "Bulgaria", "BF": "Burkina Faso", "BI": "Burundi", "KH": "Cambodia",
      "CM": "Cameroon", "CA": "Canada", "CV": "Cape Verde", "CF": "Central African Republic", "TD": "Chad",
      "CL": "Chile", "CN": "China", "CO": "Colombia", "KM": "Comoros", "CG": "Congo", "CD": "Congo, Democratic Republic",
      "CR": "Costa Rica", "CI": "Cote d'Ivoire", "HR": "Croatia", "CU": "Cuba", "CY": "Cyprus", "CZ": "Czech Republic",
      "DK": "Denmark", "DJ": "Djibouti", "DM": "Dominica", "DO": "Dominican Republic", "EC": "Ecuador", "EG": "Egypt",
      "SV": "El Salvador", "GQ": "Equatorial Guinea", "ER": "Eritrea", "EE": "Estonia", "ET": "Ethiopia", "FJ": "Fiji",
      "FI": "Finland", "FR": "France", "GA": "Gabon", "GM": "Gambia", "GE": "Georgia", "DE": "Germany", "GH": "Ghana",
      "GR": "Greece", "GT": "Guatemala", "GN": "Guinea", "GW": "Guinea-Bissau", "GY": "Guyana", "HT": "Haiti",
      "HN": "Honduras", "HK": "Hong Kong", "HU": "Hungary", "IS": "Iceland", "IN": "India", "ID": "Indonesia",
      "IR": "Iran", "IQ": "Iraq", "IE": "Ireland", "IL": "Israel", "IT": "Italy", "JM": "Jamaica", "JP": "Japan",
      "JO": "Jordan", "KZ": "Kazakhstan", "KE": "Kenya", "KP": "Korea, North", "KR": "Korea, South", "KW": "Kuwait",
      "KG": "Kyrgyzstan", "LA": "Laos", "LV": "Latvia", "LB": "Lebanon", "LS": "Lesotho", "LR": "Liberia",
      "LY": "Libya", "LI": "Liechtenstein", "LT": "Lithuania", "LU": "Luxembourg", "MO": "Macao", "MK": "North Macedonia",
      "MG": "Madagascar", "MW": "Malawi", "MY": "Malaysia", "MV": "Maldives", "ML": "Mali", "MT": "Malta",
      "MX": "Mexico", "MD": "Moldova", "MC": "Monaco", "MN": "Mongolia", "ME": "Montenegro", "MA": "Morocco",
      "MZ": "Mozambique", "MM": "Myanmar", "NA": "Namibia", "NP": "Nepal", "NL": "Netherlands", "NZ": "New Zealand",
      "NI": "Nicaragua", "NE": "Niger", "NG": "Nigeria", "NO": "Norway", "OM": "Oman", "PK": "Pakistan", "PA": "Panama",
      "PG": "Papua New Guinea", "PY": "Paraguay", "PE": "Peru", "PH": "Philippines", "PL": "Poland", "PT": "Portugal",
      "QA": "Qatar", "RO": "Romania", "RU": "Russian Federation", "RW": "Rwanda", "SA": "Saudi Arabia", "SN": "Senegal",
      "RS": "Serbia", "SC": "Seychelles", "SL": "Sierra Leone", "SG": "Singapore", "SK": "Slovakia", "SI": "Slovenia",
      "SO": "Somalia", "ZA": "South Africa", "ES": "Spain", "LK": "Sri Lanka", "SD": "Sudan", "SE": "Sweden",
      "CH": "Switzerland", "SY": "Syria", "TW": "Taiwan", "TJ": "Tajikistan", "TZ": "Tanzania", "TH": "Thailand",
      "TN": "Tunisia", "TR": "Turkey", "UG": "Uganda", "UA": "Ukraine", "AE": "United Arab Emirates",
      "GB": "United Kingdom", "US": "United States", "UY": "Uruguay", "UZ": "Uzbekistan", "VE": "Venezuela",
      "VN": "Vietnam", "YE": "Yemen", "ZM": "Zambia", "ZW": "Zimbabwe"
    };

    const rawCC = String(data.data?.countryCode || '').toUpperCase().trim();
    const resolvedCountry = data.data?.countryName || ISO_MAP[rawCC] || (rawCC.length > 2 ? rawCC : (rawCC ? `Country (${rawCC})` : null));

    result.threat_intelligence.abuseipdb = {
      status: "success",
      confidence: score,
      reports: data.data.totalReports ?? null,
      tor: data.data.isTor ?? null,
      country: resolvedCountry,
      country_code: rawCC,
      isp: data.data.isp ?? null,
      domain: data.data.domain ?? null,
    };

    addSource("AbuseIPDB");

    if (score >= 80) {
      result.risk_score += 30;

      addEvidence(
        `AbuseIPDB confidence score is ${score}/100`
      );
    } else if (score >= 50) {
      result.risk_score += 15;

      addEvidence(
        `AbuseIPDB confidence score is ${score}/100`
      );
    } else if (score > 0) {
      result.risk_score += 5;

      addEvidence(
        `AbuseIPDB confidence score is ${score}/100`
      );
    }
  }


  // ----------------------------------------------------------
  // VirusTotal
  // ----------------------------------------------------------

  if (data.data?.attributes) {
    const attributes = data.data.attributes;

    const stats =
      attributes.last_analysis_stats ?? {};

    const malicious =
      Number(stats.malicious) || 0;

    const suspicious =
      Number(stats.suspicious) || 0;

    result.threat_intelligence.virustotal = {
      status: "success",
      reputation:
        attributes.reputation ?? null,
      malicious,
      suspicious,
      harmless:
        Number(stats.harmless) || 0,
      undetected:
        Number(stats.undetected) || 0,
    };

    addSource("VirusTotal");

    if (malicious >= 10) {
      result.risk_score += 25;

      addEvidence(
        `VirusTotal reported ${malicious} malicious detections`
      );
    } else if (malicious > 0) {
      result.risk_score += 15;

      addEvidence(
        `VirusTotal reported ${malicious} malicious detections`
      );
    }

    if (suspicious > 0) {
      addEvidence(
        `VirusTotal reported ${suspicious} suspicious detections`
      );
    }
  }


  // ----------------------------------------------------------
  // AlienVault OTX
  // ----------------------------------------------------------

  if (data.pulse_info !== undefined) {
    const pulses =
      Number(data.pulse_info?.count) || 0;

    result.threat_intelligence.otx = {
      status: "success",
      pulses,
    };

    addSource("AlienVault OTX");

    if (pulses > 0) {
      result.risk_score += 15;

      addEvidence(
        `AlienVault OTX has ${pulses} associated pulses`
      );
    }
  }


  // ----------------------------------------------------------
  // ThreatFox
  // ----------------------------------------------------------

  if (data.query_status !== undefined) {
    const status =
      data.query_status === "no_result"
        ? "no_result"
        : "success";

    result.threat_intelligence.threatfox = {
      status,
      result:
        typeof data.data === "string"
          ? data.data
          : data.data ?? null,
    };

    addSource("ThreatFox");

    if (status === "success") {
      addEvidence(
        "ThreatFox returned an IOC result"
      );
    }
  }


  // ----------------------------------------------------------
  // LeakIX SUCCESS
  // ----------------------------------------------------------

  if (
    data.services !== undefined ||
    data.summary !== undefined ||
    data.host !== undefined
  ) {
    result.threat_intelligence.leakix = {
      status: "success",

      services:
        Array.isArray(data.services)
          ? data.services
          : [],

      error: null,
    };

    addSource("LeakIX");

    if (
      Array.isArray(data.services) &&
      data.services.length > 0
    ) {
      addEvidence(
        `LeakIX reported ${data.services.length} exposed services`
      );
    }
  }


  // ----------------------------------------------------------
  // PROVIDER ERROR
  // ----------------------------------------------------------

  if (data.error) {
    const errorCode =
      data.error.code ?? null;

    const errorMessage =
      data.error.message ??
      "Unknown provider error";

    // LeakIX timeout/error
    if (
      errorCode === "ETIMEDOUT" ||
      errorMessage.toLowerCase().includes("leakix")
    ) {
      result.threat_intelligence.leakix = {
        status: "unavailable",
        services: [],
        error: errorCode ?? errorMessage,
      };

      addSource("LeakIX");

      addEvidence(
