  alert.srcip,
  alert.dstip,
  alert.src_ip,
  alert.dst_ip,
  alert.source_ip,
  alert.destination_ip,

  alert.ip
];

for (const value of knownIPs) {
  processIP(value);
}


// ------------------------------------------------------------
// URL extraction
// ------------------------------------------------------------

function processURL(value) {
  if (typeof value !== 'string') return;

  const v = value.trim();

  if (/^https?:\/\//i.test(v)) {
    urls.add(v);
  }
}


const knownURLs = [
