// ------------------------------------------------------------
// Hash extraction
// ------------------------------------------------------------

function processHash(value) {
  if (typeof value !== 'string') return;

  const hash = value.trim().toLowerCase();

  if (/^[a-f0-9]{32}$/.test(hash)) {
    hashes.add(hash);
    return;
  }

  if (/^[a-f0-9]{40}$/.test(hash)) {
    hashes.add(hash);
    return;
  }

  if (/^[a-f0-9]{64}$/.test(hash)) {
    hashes.add(hash);
  }
}


const knownHashes = [
  alert.data?.md5,
  alert.data?.sha1,
  alert.data?.sha256,
  alert.data?.hash,
  alert.data?.file_hash,

  alert.md5,
  alert.sha1,
  alert.sha256,
  alert.hash,
  alert.file_hash
];

