// ------------------------------------------------------------
// Domain extraction
// ------------------------------------------------------------
//
// IMPORTANT:
// Do NOT treat arbitrary "word.extension" strings such as:
//
//   malicious.html
//   malware.exe
//   document.pdf
//
// as domains.
//
// We therefore only accept recognized public DNS suffixes here.
// ------------------------------------------------------------

const VALID_TLDS = new Set([
  'com',
  'net',
  'org',
  'io',
  'co',
  'in',
  'uk',
  'de',
  'fr',
  'us',
  'ca',
  'au',
  'info',
  'biz',
  'xyz',
  'online',
  'site',
  'app',
  'dev',
  'cloud',
  'me',
  'tv',
  'tech',
  'pro',
  'gov',
  'edu'
]);


function isPlausibleDomain(value) {
  if (typeof value !== 'string') return false;

  let domain = value.trim().toLowerCase();

  // Remove URL prefix if present
  domain = domain.replace(/^https?:\/\//, '');

  // Remove path
  domain = domain.split('/')[0];

  // Remove port
  domain = domain.split(':')[0];

  if (!domain.includes('.')) return false;

  const parts = domain.split('.');

  if (parts.length < 2) return false;

  const tld = parts[parts.length - 1];

  if (!VALID_TLDS.has(tld)) {
    return false;
  }

  // Basic domain label validation
  for (const part of parts) {
    if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(part)) {
      return false;
    }
  }

  // Never treat obvious file extensions as domains
  const fileExtensions = new Set([
    'html',
    'htm',
    'exe',
    'dll',
    'js',
    'json',
    'xml',
    'txt',
    'pdf',
    'doc',
    'docx',
    'xls',
    'xlsx',
    'zip',
    'rar',
    '7z',
    'png',
    'jpg',
    'jpeg',
    'gif',
    'bmp',
    'svg',
    'log',
    'conf',
    'cfg',
    'ini',
    'sh',
    'bat',
    'ps1',
    'py',
    'java'
  ]);

  if (fileExtensions.has(tld)) {
    return false;
  }

  return true;
}


function processDomain(value) {
  if (!isPlausibleDomain(value)) return;

  let domain = value.trim().toLowerCase();

  domain = domain.replace(/^https?:\/\//, '');
  domain = domain.split('/')[0];
  domain = domain.split(':')[0];

  domains.add(domain);
}


// Known domain fields
const knownDomains = [
  alert.data?.domain,
  alert.data?.hostname,
  alert.data?.host,

  alert.domain,
  alert.hostname,
  alert.host
];

for (const value of knownDomains) {
  processDomain(value);
}


// ------------------------------------------------------------
// Scan arbitrary nested content
// ------------------------------------------------------------

function scanText(text) {
  if (typeof text !== 'string') return;

  // ----------------------------
  // URLs
  // ----------------------------

  const foundURLs =
    text.match(
      /\bhttps?:\/\/[^\s"'<>]+/gi
    ) ?? [];

  for (const rawURL of foundURLs) {
    const cleanURL =
      rawURL.replace(/[),.;]+$/, '');

    processURL(cleanURL);
  }


  // ----------------------------
  // IPv4
  // ----------------------------

  const foundIPs =
    text.match(
      /\b(?:\d{1,3}\.){3}\d{1,3}\b/g
    ) ?? [];

  for (const ip of foundIPs) {
    processIP(ip);
  }


  // ----------------------------
  // Hashes
  // ----------------------------

  const foundHashes =
    text.match(
      /\b[a-fA-F0-9]{32}\b|\b[a-fA-F0-9]{40}\b|\b[a-fA-F0-9]{64}\b/g
    ) ?? [];

  for (const hash of foundHashes) {
    processHash(hash);
  }


  // ----------------------------
  // Domains
  // ----------------------------

  const foundDomainCandidates =
    text.match(
      /\b(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}\b/g
    ) ?? [];

  for (const candidate of foundDomainCandidates) {
    processDomain(candidate);
  }
}


function scan(value, depth = 0) {
  // Prevent excessive recursion
  if (depth > 10) return;

  if (value === null || value === undefined) {
    return;
  }

  // String
  if (typeof value === 'string') {
    scanText(value);
    return;
  }

  // Array
  if (Array.isArray(value)) {
    for (const item of value) {
      scan(item, depth + 1);
    }
    return;
  }

  // Object
  if (typeof value === 'object') {

    for (const [key, child] of Object.entries(value)) {

      const keyLower = key.toLowerCase();


      // ----------------------------
      // Hash fields
      // ----------------------------

      if (
        keyLower === 'md5' ||
        keyLower === 'sha1' ||
        keyLower === 'sha256' ||
        keyLower.includes('file_hash') ||
        keyLower === 'hash'
      ) {
        processHash(child);
      }


      // ----------------------------
      // IP fields
      // ----------------------------

      if (
        keyLower === 'srcip' ||
        keyLower === 'dstip' ||
        keyLower === 'src_ip' ||
        keyLower === 'dst_ip' ||
        keyLower === 'source_ip' ||
        keyLower === 'destination_ip'
      ) {
        processIP(child);
      }


      // ----------------------------
      // URL fields
      // ----------------------------

      if (
        keyLower === 'url' ||
        keyLower === 'uri' ||
        keyLower === 'link'
      ) {
        processURL(child);
      }


      // ----------------------------
      // Domain fields
      // ----------------------------

      if (
        keyLower === 'domain' ||
        keyLower === 'hostname'
      ) {
        processDomain(child);
      }


      // Continue recursively
      scan(child, depth + 1);
    }
  }
}


// Scan everything
scan(alert);


// Explicit free-text sources
if (typeof alert.full_log === 'string') {
  scanText(alert.full_log);
}

if (typeof alert.rule?.description === 'string') {
  scanText(alert.rule.description);
