// ============================================================
// DEDUP CHECK (ENTERPRISE FINGERPRINTING & DE-SPAM)
// ============================================================
const DEDUP_WINDOW_MS = 180 * 1000; // 3-minute dedup window
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenAlerts) staticData.seenAlerts = {};

const data = $input.first().json;

// Check test bypass
if (data.test || data.body?.test || data.original_alert?.test) {
