}

// Clean up old entries
const now = Date.now();
for (const [k, ts] of Object.entries(staticData.seenAlerts)) {
  if (now - Number(ts) > DEDUP_WINDOW_MS) {
    delete staticData.seenAlerts[k];
  }
}

// Extract identity fields
const alertObj = (data.body && typeof data.body === 'object') ? data.body : (data.original_alert ?? data);
const ruleId = String(alertObj.rule?.id || data.rule_id || 'norule');
const agentName = String(alertObj.agent?.name || data.agent_name || 'blusoc');
