const command = String(alertObj.data?.command || '');
const user = String(alertObj.data?.srcuser || alertObj.data?.user || '');

// Build unique deduplication fingerprint
// High-volume telemetry families (vulnerability findings 235xx, compliance 19xxx,
// O365 audit 915xx, Suricata decode noise 8661x) are fingerprinted by rule+agent
// only, so a vulnerability scan or audit burst cannot flood the SOAR pipeline.
const HIGH_VOLUME = /^(235\d|19\d{3}|915\d{2}|8661[123])$/.test(ruleId);
let dedupKey = "";
if (HIGH_VOLUME) {
  dedupKey = `HV|${ruleId}|${agentName}`;
