  dedupKey = `EXT|${ruleId}|${agentName}|${sourceIp}`;
} else if (command || user) {
  dedupKey = `INT|${ruleId}|${agentName}|${user}|${command}`;
} else {
  dedupKey = `GEN|${ruleId}|${agentName}|${alertObj.rule?.description || 'alert'}`;
}

// If already seen in current window, SUPPRESS duplicate!
if (staticData.seenAlerts[dedupKey]) {
  return [];
}

// Mark as seen
staticData.seenAlerts[dedupKey] = now;
