// ============================================================

const data = $input.first().json;
const incident = data.incident ?? data;

const ruleLevel = Number(incident.rule_level ?? 0);
const ti = incident.threat_intelligence ?? {};
const assessment = incident.assessment ?? {};
const maliciousSources = assessment.malicious_sources ?? [];
const hasMaliciousEvidence = assessment.has_malicious_evidence === true || maliciousSources.length > 0;
const riskScore = Number(incident.risk_score ?? assessment.risk_score ?? 0);

// Telemetry classification: Routine low-level telemetry with no malicious evidence
if (ruleLevel < 7 && !hasMaliciousEvidence) {
  incident.assessment = incident.assessment ?? {};
  incident.assessment.verdict = 'BENIGN_TELEMETRY';
  incident.assessment.confidence = 'HIGH';
  incident.severity = 'LOW';
  incident.laya_verification = {
    stage: "Secondary Verification",
    verdict: 'BENIGN_TELEMETRY',
    confidence: 'HIGH',
    rule_level: ruleLevel,
    evaluated_at: new Date().toISOString()
  };
  return [{ json: { incident } }];
}

// ------------------------------------------------------------
// SCENARIO 3: INTERNAL ALERT (RFC 1918 / Local System Event)
// ------------------------------------------------------------
if (incident.analysis_type === 'internal') {
  const internal = incident.internal_analysis ?? {};
  incident.assessment = incident.assessment ?? {};
  incident.assessment.verdict = (ruleLevel >= 10) ? 'INTERNAL_SECURITY_EVENT' : 'BENIGN_INTERNAL_EVENT';
  incident.assessment.confidence = (ruleLevel >= 10) ? 'HIGH' : 'MEDIUM';
  incident.severity = (ruleLevel >= 12) ? 'CRITICAL' : (ruleLevel >= 10) ? 'HIGH' : (ruleLevel >= 8) ? 'MEDIUM' : 'LOW';

  incident.laya_verification = {
    stage: "Secondary Verification",
    verdict: incident.assessment.verdict,
    confidence: incident.assessment.confidence,
    rule_level: ruleLevel,
    evaluated_at: new Date().toISOString()
  };
  return [{ json: { incident } }];
}

// ------------------------------------------------------------
// SCENARIOS 1 & 2: EXTERNAL ALERTS (Corroborated vs Training)
// ------------------------------------------------------------

if (hasMaliciousEvidence || riskScore >= 50) {
  // Scenario 1: Confirmed Threat Intelligence Corroboration
  incident.assessment.verdict = 'TRUE_POSITIVE_THREAT';
  incident.severity = (riskScore >= 80 || ruleLevel >= 12) ? 'CRITICAL' : 'HIGH';
  incident.assessment.confidence = (maliciousSources.length >= 2) ? 'HIGH' : 'MEDIUM';
} else {
  // Scenario 2: Student Training Alert or Uncorroborated Lab IP
  incident.assessment.verdict = 'UNCORROBORATED_OR_TRAINING';
  incident.assessment.confidence = 'LOW';
  incident.severity = (ruleLevel >= 12) ? 'HIGH' : (ruleLevel >= 8) ? 'MEDIUM' : 'LOW';
  incident.assessment.evidence = incident.assessment.evidence ?? [];
  incident.assessment.evidence.push(
    `Rule level ${ruleLevel} triggered. External threat intelligence providers reported 0 malicious indicators. Forwarded for student analyst triage.`
  );
}

incident.laya_verification = {
  stage: "Secondary Verification",
  verdict: incident.assessment.verdict,
  confidence: incident.assessment.confidence,
  risk_score: riskScore,
  has_malicious_evidence: hasMaliciousEvidence,
  evaluated_at: new Date().toISOString()
};

return [{ json: { incident } }];

// ============================================================
// EXTERNAL INCIDENT NORMALIZER
// ============================================================
// Wraps TI Normalizer output into { incident: {...} }
// to match Internal Incident schema.
// Both branches now produce one common schema for Merge2.
// ============================================================

const data = $input.first().json;

const alert = data.alert ?? {};
const ti = data.threat_intelligence ?? {};
const assessment = data.assessment ?? {};

const incident = {
  original_alert: alert.original_alert ?? data.original_alert ?? null,
  rule_id: alert.rule_id ?? alert.original_alert?.rule?.id ?? 'N/A',
  raw_log: alert.raw_log ?? alert.original_alert?.full_log ?? null,
  source_ip: alert.source_ip ?? null,
  agent_name: alert.agent_name ?? null,
  rule_level: alert.rule_level ?? null,
  description: alert.description ?? null,
  severity: alert.severity ?? 'LOW',
  risk_score: Number(alert.risk_score ?? 0),

  ioc: alert.ioc ?? { type: null, value: null },

  analysis_type: 'external',

  internal_analysis: null,

  threat_intelligence: ti,

  assessment: {
    confidence: assessment.confidence ?? 'LOW',
    provider_coverage: assessment.provider_coverage ?? 0,
    has_malicious_evidence: assessment.has_malicious_evidence ?? false,
    malicious_sources: assessment.malicious_sources ?? [],
    evidence: assessment.evidence ?? [],
    provider_failures: assessment.provider_failures ?? [],
  },

  summary: null,
  recommendation: null,
};

return [{ json: { incident } }];

// ============================================================
// LAYA - PRIMARY ALERT JUDGEMENT (INITIAL DETERMINATION)
// ============================================================
// Determines whether incoming alert requires external Threat Intel
// or internal host metric analysis, establishing the primary hypothesis.
// ============================================================

const data = $input.first().json;
const alert = (data.body && typeof data.body === 'object') ? data.body : (data.original_alert ?? data);

function isPrivateOrLocalIP(ip) {
  if (!ip || typeof ip !== 'string') return true;
  const clean = ip.trim();
  if (clean === 'localhost' || clean === '127.0.0.1' || clean === '::1' || clean === '0.0.0.0') return true;

  const parts = clean.split('.');
  if (parts.length !== 4) return true;
  const nums = parts.map(Number);
  if (nums.some(isNaN)) return true;

  const [a, b, c, d] = nums;

  // RFC 1918 Private Ranges
  if (a === 10) return true;
  if (a === 172 && (b >= 16 && b <= 31)) return true;
  if (a === 192 && b === 168) return true;

  // Loopback / Link-Local / Tailscale / Multicast / Broadcast
  if (a === 127) return true;
  if (a === 169 && b === 254) return true;
  if (a === 100 && (b >= 64 && b <= 127)) return true;
  if (a === 0 || a >= 224) return true;

  return false;
}

function isValidHash(val) {
  if (!val || typeof val !== 'string') return false;
  const clean = val.trim().toLowerCase();
  return /^[a-f0-9]{32}$/.test(clean) || /^[a-f0-9]{40}$/.test(clean) || /^[a-f0-9]{64}$/.test(clean);
}

// 1. Candidate IPs from telemetry
const candidateIps = [
  alert.data?.srcip,
  alert.data?.src_ip,
  alert.data?.source_ip,
  alert.srcip,
  alert.source_ip,
  data.source_ip,
  data.ioc?.value
].filter(Boolean);

let verifiedPublicIP = null;
for (const ip of candidateIps) {
  if (typeof ip === 'string' && !isPrivateOrLocalIP(ip)) {
    verifiedPublicIP = ip.trim();
    break;
  }
}

// 2. Candidate Hashes
const candidateHashes = [
  alert.data?.md5,
  alert.data?.sha1,
  alert.data?.sha256,
  alert.data?.hash,
  alert.data?.file_hash,
  alert.syscheck?.md5_after,
  alert.syscheck?.sha1_after,
  alert.syscheck?.sha256_after,
  alert.md5,
  alert.sha1,
  alert.sha256
].filter(Boolean);

let verifiedHash = null;
for (const h of candidateHashes) {
  if (isValidHash(h)) {
    verifiedHash = h.trim().toLowerCase();
    break;
  }
}

// 3. Local Host Event Detection
const isLocalHostEvent = Boolean(
  alert.rule?.groups?.includes('sudo') ||
  alert.rule?.groups?.includes('pam') ||
  alert.rule?.groups?.includes('syslog') ||
  alert.location === 'journald' ||
  alert.data?.srcuser !== undefined ||
  alert.data?.command !== undefined
);

let triggerThreatIntel = false;
let gatekeeperReason = "";
let verifiedIOC = null;

if (verifiedPublicIP && !isLocalHostEvent) {
  triggerThreatIntel = true;
  verifiedIOC = { type: 'public_ip', value: verifiedPublicIP };
  gatekeeperReason = `Verified public IP: ${verifiedPublicIP}`;
} else if (verifiedHash) {
  triggerThreatIntel = true;
  verifiedIOC = { type: 'hash', value: verifiedHash };
  gatekeeperReason = `Verified artifact file hash: ${verifiedHash}`;
} else {
  triggerThreatIntel = false;
  verifiedIOC = { type: 'none', value: null };
  gatekeeperReason = isLocalHostEvent
    ? "Internal host event - TI bypassed to preserve API quota"
    : "Private IP or local telemetry - TI bypassed to preserve API quota";
}

return [{
  json: {
    ...data,
    ti_required: triggerThreatIntel,
    laya_primary: {
      stage: "Primary Determination",
      verdict: triggerThreatIntel ? "EXTERNAL_TI_REQUIRED" : "INTERNAL_METRIC_ANALYSIS",
      reason: gatekeeperReason,
      public_ip: verifiedPublicIP,
      hash: verifiedHash,
      timestamp: new Date().toISOString()
    },
    gatekeeper: {
      decision: triggerThreatIntel ? "TRIGGER_TI" : "BYPASS_TI",
      reason: gatekeeperReason,
      public_ip: verifiedPublicIP,
      hash: verifiedHash
    },
    source_ip: verifiedPublicIP ?? candidateIps[0] ?? null,
    ioc: verifiedIOC
  }
}];

// ============================================================
// LAYA - HUMAN INTERVENTION GATEKEEPER (v3.3)
// ============================================================
// Authoritative decision: delegates to the Laya engine (:9999) and routes on
// its verdict. Fail-safe if the engine is unreachable (escalate, never drop).
// On escalation it stamps the Laya correlation id + decision into the IRIS
// payload so IRIS and Discord tickets reference the same decision record.
// ============================================================

const data = $input.first().json;
const report = data.report ?? {};
const incident = data.incident ?? {};

const firstStr = (...vals) => {
  for (const v of vals) {
    if (v === undefined || v === null) continue;
    const s = String(v).trim();
    if (s !== '' && s !== 'undefined' && s !== 'null') return s;
  }
  return '';
};
const firstNum = (...vals) => {
  for (const v of vals) {
    if (v === undefined || v === null || v === '') continue;
    const n = Number(v);
    if (Number.isFinite(n)) return n;
  }
  return 0;
};

const ruleLevel = firstNum(report.rule_level, incident.rule_level, data.rule_level, data.rule?.level);
const ruleId = firstStr(report.rule_id, incident.rule_id, data.rule_id, 'N/A');
const description = firstStr(report.description, incident.description, data.description, 'Security Event');
const sourceIp = firstStr(report.source_ip, incident.source_ip, data.source_ip, data.candidate_ip, incident.original_alert?.data?.srcip);
const agentName = firstStr(report.agent_name, incident.agent_name, data.agent_name, data.host, 'unknown');
const severity = firstStr(report.severity, data.severity, incident.severity, 'MEDIUM').toUpperCase();
const riskScore = firstNum(report.risk_score, incident.risk_score, data.risk_score);
const srcUser = firstStr(
  report.srcuser, report.internal_analysis?.user,
  incident.original_alert?.data?.srcuser, incident.original_alert?.data?.user,
  data.original_alert?.data?.srcuser, data.srcuser, ''
);

const triagePayload = {
  timestamp: new Date().toISOString(),
  host: agentName,
  vendor: incident.vendor ?? report.vendor ?? 'Wazuh',
  rule_id: ruleId,
  rule_level: ruleLevel,
  description,
  source_ip: sourceIp,
  srcuser: srcUser,
  severity,
  risk_score: riskScore,
  threat_intelligence: report.threat_intelligence ?? incident.threat_intelligence ?? {},
  assessment: report.assessment ?? incident.assessment ?? {},
  groups: (report.raw_alert?.rule?.groups) ?? incident?.original_alert?.rule?.groups ?? [],
  raw_alert: report.raw_alert ?? incident?.original_alert ?? null,
};

let layaDecision = null;
try {
  if (typeof fetch === 'function') {
    const res = await fetch('http://REPLACE_WITH_LAYA_HOST:9999/api/triage', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(triagePayload)
    });
    layaDecision = await res.json();
  } else if (this.helpers && this.helpers.httpRequest) {
    layaDecision = await this.helpers.httpRequest({
      method: 'POST', url: 'http://REPLACE_WITH_LAYA_HOST:9999/api/triage',
      body: triagePayload, json: true
    });
  }
} catch (e) {
  // Fail-safe: engine unreachable => escalate anything material, never drop.
  layaDecision = {
    action: (ruleLevel >= 8 || severity === 'HIGH' || severity === 'CRITICAL') ? 'ESCALATED' : 'CLOSED_NO_IMPACT',
    verdict: 'ENGINE_UNAVAILABLE', confidence: 0.50, layer: 4,
    stage: 'L4 Fail-Safe (engine unreachable)',
    reason: `Laya engine unreachable: ${(e && e.message) ? e.message : e}`,
    laya_model_used: false, latency_ms: 0, correlation_id: 'lay-offline'
  };
}

const action = layaDecision?.action ?? layaDecision?.decision ?? 'ESCALATED';

if (action !== 'ESCALATED') {
  // Auto-closed with no impact - no IRIS / Discord / Telegram / Slack / FortiGate.
  return [];
}

// ---- enrich the IRIS payload with the Laya decision (correlation) ----
const cid = layaDecision?.correlation_id ?? '';
const layerTag = (layaDecision?.layer === null || layaDecision?.layer === undefined) ? '' : ('L' + layaDecision.layer);
const verdict = layaDecision?.verdict ?? 'UNCORROBORATED_OR_TRAINING';
const confPct = Math.round((Number(layaDecision?.confidence) || 0) * 100);

const irisPayload = Object.assign({}, data.iris_payload || {});
irisPayload.alert_title = String(irisPayload.alert_title || 'Security Incident')
  + ' [Laya ' + verdict.replace(/_/g, ' ') + ']';
irisPayload.alert_source_ref = [irisPayload.alert_source_ref || 'soar', cid].filter(Boolean).join('|');
irisPayload.alert_tags = [irisPayload.alert_tags || '', 'laya', layerTag, verdict, cid].filter(Boolean).join(',');
irisPayload.alert_description = (irisPayload.alert_description || '') +
  '\n\n[LAYA DECISION RECORD]\n' +
  'Correlation ID : ' + cid + '\n' +
  'Decision layer : ' + (layerTag || 'n/a') + '  ' + (layaDecision?.stage || '') + '\n' +
  'Verdict        : ' + verdict + '\n' +
  'Confidence     : ' + confPct + '%\n' +
  'Decided by     : ' + (layaDecision?.laya_model_used ? 'Laya System 1 decision engine neural model' : 'deterministic guardrail') + '\n' +
  'Engine latency : ' + (layaDecision?.latency_ms ?? 0) + ' ms\n' +
  'Reason         : ' + (layaDecision?.reason || '');

return [{
  json: {
    ...data,
    severity,
    iris_payload: irisPayload,
    laya_gate: {
      human_intervention_required: true,
      action: 'ESCALATED',
      correlation_id: cid,
      layer: (layaDecision?.layer === undefined) ? null : layaDecision.layer,
      verdict: verdict,
      confidence: Number(layaDecision?.confidence) || 0.90,
      reason: layaDecision?.reason || 'Escalated by Laya engine',
      stage: layaDecision?.stage || 'Laya System 1 decision engine',
      latency_ms: layaDecision?.latency_ms ?? 0,
      model_latency_ms: layaDecision?.model_latency_ms ?? null,
      laya_model_used: !!layaDecision?.laya_model_used,
      policy_version: layaDecision?.policy_version ?? '5.0',
      evaluated_at: new Date().toISOString()
    }
  }
}];
